import org.apache.commons.math3.distribution.BinomialDistribution;
import java.util.Arrays;

public class Main {
  public static void main(String[] args) {
      // En Java corporativo se utilizaría un objeto modelador:
      int ensayos = 10;
      double probabilidad = 0.5;

      BinomialDistribution dist = new BinomialDistribution(ensayos, probabilidad);

      // Repetir experimento 10 veces
      int[] resultados = dist.sample(10);
      System.out.println(Arrays.toString(resultados));
  }
}
